    output.reserve(x.size());

    // Initialize the last element of output to the last element of x
    output.push_back(x.back());

    // Iterate in reverse and compute the prefix sum
    for (int i = x.size() - 2; i >= 0; i--) {
        output.push_back(x[i] + output.back());
