    double thetaT = 2.0 * M_PI / N;
    std::complex<double> phiT = std::complex<double>(std::cos(thetaT), -std::sin(thetaT)), T;
    // Bit reversal
    for (unsigned int i = 0; i < N; i++) {
        unsigned int j = i, r = 0;
        while (j) {
            r <<= 1;
            r |= j & 1;
            j >>= 1;
        }
        if (i < r) {
            output[i] = x[r];
        }
    }
    // Compute the FFT
    while (k > 1) {
        n = k;
        k >>= 1;
        phiT = phiT * phiT;
        T = 1.0L;
        for (unsigned int l = 0; l < k; l++) {
            for (unsigned int a = l; a < N; a += n) {
                unsigned int b = a + k;
                std::complex<double> t = output[a] - output[b];
                output[a] += output[b];
                output[b] = t * T;
            }
            T *= phiT;
        }
    }
}

