   output: [{4,0}, {1,-2.42421}, {0,0}, {1,-0.414214}, {0,0}, {1,0.414214}, {0,0}, {1,2.41421}]
*/
void fft(std::vector<std::complex<double>> const& x, std::vector<std::complex<double>> &output) {
    unsigned int N = x.size();
    output.resize(N);

    // Bit reversal
    for (unsigned int i = 0; i < N; i++) {
        unsigned int j = i, k = 0;
        while (j) {
            k = (k << 1) | (j & 1);
            j >>= 1;
        }
        if (i < k) {
            output[i] = x[k];
        }
    }

    // Compute the FFT
    for (unsigned int len = 2; len <= N; len <<= 1) {
        double ang = 2 * M_PI / len;
        std::complex<double> wlen(std::cos(ang), std::sin(ang));
        for (unsigned int i = 0; i < N; i += len) {
            std::complex<double> w(1);
            for (unsigned int j = 0; j < len / 2; j++) {
                std::complex<double> u = output[i + j];
                std::complex<double> v = output[i + j + len / 2] * w;
                output[i + j] = u + v;
                output[i + j + len / 2] = u - v;
                w *= wlen;
            }
        }
    }
}

