            for (unsigned int j = 0; j < halfLen; j++) {
                std::complex<double> u = output[i + j];
                std::complex<double> v = output[i + j + halfLen] * w;
                output[i + j] = u + v;
                output[i + j + halfLen] = u - v;
                w *= wlen;
            }
        }
    }
