#include <algorithm> // for std::transform

/* Compute z = alpha*x+y where x and y are vectors. Store the result in z.
   Example:

   input: x=[1, -5, 2, 9] y=[0, 4, 1, -1] alpha=2
   output: z=[2, -6, 5, 17]
*/
void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
   // Check if the input vectors have the same size
   if (x.size()!= y.size() || x.size()!= z.size()) {
      throw std::invalid_argument("Vectors must have the same size");
   }

   // Use std::transform to perform element-wise addition and multiplication
   std::transform(x.begin(), x.end(), y.begin(), z.begin(), [alpha](double a, double b) {
      return alpha * a + b;
   });
}

