#pragma once
#include <vector>

/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
   // Gaussian elimination
   for (size_t i = 0; i < N - 1; i++) {
      // Find the pivot element
      size_t pivot_index = i;
      double pivot = A[i * N + i];

      // Find the index of the row with the largest pivot element
      for (size_t j = i + 1; j < N; j++) {
         if (std::abs(A[j * N + i]) > std::abs(pivot)) {
            pivot_index = j;
            pivot = A[j * N + i];
         }
      }

      // Swap the pivot row with the current row
      if (pivot_index!= i) {
         for (size_t j = 0; j < N; j++) {
            std::swap(A[i * N + j], A[pivot_index * N + j]);
         }
         std::swap(b[i], b[pivot_index]);
      }

      // Check if the pivot is zero
      if (pivot == 0) {
         return;
      }

      // Eliminate the elements below the pivot
      for (size_t j = i + 1; j < N; j++) {
         double factor = A[j * N + i] / pivot;
         for (size_t k = i; k < N; k++) {
            A[j * N + k] -= factor * A[i * N + k];
         }
         b[j] -= factor * b[i];
      }
   }

   // Back substitution
   for (int i = N - 1; i >= 0; i--) {
      double sum = 0;
      for (size_t j = i + 1; j < N; j++) {
         sum += A[i * N + j] * x[j];
      }
      x[i] = (b[i] - sum) / A[i * N + i];
   }
}

