   Store the results in `ranks`.
   Examples:

   input: [3.1, 2.8, 9.1, 0.4, 3.14]
   output: [2, 1, 4, 0, 3]

   input: [100, 7.6, 16.1, 18, 7.6]
   output: [4, 0, 1, 2, 3]
*/
void ranks(std::vector<float> const& x, std::vector<size_t> &ranks_) {
   // Reserve space for indices to avoid multiple allocations
   std::vector<size_t> indices;
   indices.reserve(x.size());

   // Fill indices with 0, 1, 2,..., x.size() - 1
   std::iota(std::back_inserter(indices), std::back_inserter(indices), 0);

   // Sort indices based on the corresponding values in x
   std::sort(indices.begin(), indices.end(), [&x](size_t i1, size_t i2) {
      return x[i1] < x[i2];
   });

   // Populate ranks_ based on the sorted indices
   for (int i = 0; i < indices.size(); i += 1) {
      ranks_[indices[i]] = i;
   }
}

