/* Find the k-th smallest element of the vector x.
   Example:

   input: x=[1, 7, 6, 0, 2, 2, 10, 6], k=4
   output: 6
*/
int findKthSmallest(std::vector<int> const& x, int k) {
   // Use a min-heap to efficiently find the k-th smallest element
   std::vector<int> heap;
   heap.reserve(k); // Reserve space for k elements

   // Build the heap
   for (int i = 0; i < k; ++i) {
      heap.push_back(x[i]);
      std::push_heap(heap.begin(), heap.end());
   }

   // Process the remaining elements
   for (int i = k; i < x.size(); ++i) {
      if (x[i] < heap[0]) {
         std::pop_heap(heap.begin(), heap.end()); // Remove the largest element
         heap.back() = x[i]; // Replace with the new element
         std::push_heap(heap.begin(), heap.end()); // Restore the heap property
      }
   }

   return heap[0]; // The root of the heap contains the k-th smallest element
}

