   output: 1
*/
size_t findClosestToPi(std::vector<double> const& x) {
   // Find the index of the first element in x that is greater than or equal to PI
   auto it = std::lower_bound(x.begin(), x.end(), M_PI);
   if (it == x.end()) {
      // If all elements in x are less than PI, return the last index
      return x.size() - 1;
   }
   size_t index = it - x.begin();
   if (index == 0) {
      // If the first element is the closest to PI, return its index
      return index;
   }
   // Compare the distance to PI of the current element and the previous element
   double diff1 = std::abs(x[index] - M_PI);
   double diff2 = std::abs(x[index - 1] - M_PI);
   return diff1 < diff2? index : index - 1;
}

